import flatpickr from 'flatpickr';
import iziToast from 'izitoast';

let intervalId;
let userSelectedDate;

const refs = {
  inputText: document.querySelector('#datetime-picker'),
  btnStr: document.querySelector('button'),
  days: document.querySelector('span[data-days]'),
  hours: document.querySelector('span[data-hours]'),
  minutes: document.querySelector('span[data-minutes]'),
  seconds: document.querySelector('span[data-seconds]'),
};

function addLeadingZero(value) {
  return String(value).padStart(2, '0');
}

const onStartBtnClick = event => {
  refs.btnStr.disabled = true;
  refs.inputText.disabled = true;
  intervalId = setInterval(() => {
    const diff = userSelectedDate - Date.now();

    if (diff <= 0) {
      clearInterval(intervalId);
      return (refs.inputText.disabled = false);
    }
    const { days, hours, minutes, seconds } = convertMs(diff);
    refs.days.textContent = addLeadingZero(days);
    refs.hours.textContent = addLeadingZero(hours);
    refs.minutes.textContent = addLeadingZero(minutes);
    refs.seconds.textContent = addLeadingZero(seconds);
  }, 1000);
};

refs.btnStr.disabled = true;
refs.btnStr.addEventListener('click', onStartBtnClick);

function convertMs(ms) {
  // Number of milliseconds per unit of time
  const second = 1000;
  const minute = second * 60;
  const hour = minute * 60;
  const day = hour * 24;

  // Remaining days
  const days = Math.floor(ms / day);
  // Remaining hours
  const hours = Math.floor((ms % day) / hour);
  // Remaining minutes
  const minutes = Math.floor(((ms % day) % hour) / minute);
  // Remaining seconds
  const seconds = Math.floor((((ms % day) % hour) % minute) / second);

  return { days, hours, minutes, seconds };
}

const optionsflatpickr = {
  enableTime: true,
  time_24hr: true,
  defaultDate: new Date(),
  minuteIncrement: 1,
  onClose(selectedDates) {
    userSelectedDate = selectedDates[0];

    if (userSelectedDate > Date.now()) {
      refs.btnStr.disabled = false;
    } else {
      refs.btnStr.disabled = true;
      iziToast.show({
        title: 'Error',
        message: 'Please choose a date in the future',
        position: 'topRight',
        color: 'red',
      });
    }

    console.log(selectedDates[0]);
  },
};

flatpickr(refs.inputText, optionsflatpickr);
